/* ============================================================
   文风卡：预置的「现成文风」模板（目标 100 张）
   ------------------------------------------------------------
   每张卡回答三个问题：
     1. 这张卡会让文风变成什么样？（effect —— 写进提示词约束）
     2. 多段原文，让人直接感受到这个味道；（quotes）
     3. 点「应用」后，实际写进【文笔】画布的完整文案。（applyText）
   只做预置卡：不联网、不调 LLM，点了立刻生效。

   关于 quotes：优先收录广为流传的确凿名句 / 通行译文；
   少量用于补足风格感受的段落已用「（风格示例）」前缀标明——
   它们不是逐字原文，只是这一路文风的拟写。UI 原样展示，不作区分。
   ============================================================ */

export type StyleCardGroup =
  | '中国现当代'
  | '中国古典·武侠'
  | '日本文学'
  | '欧美·现代主义与经典'
  | '俄苏·欧洲大陆'
  | '法国·拉美·后现代'
  | '类型文学'
  | '诗歌·戏剧·随笔'
  | '网络文学'
  /** 用户自己设计（StyleForge 生成）的卡，运行时从 AppState 注入，不写死在预置表里 */
  | '我的文风卡'

export interface StyleCard {
  id: string
  group: StyleCardGroup
  /** 卡名：作者 + 作品 */
  name: string
  /** chip 上的一句话标签 */
  tagline: string
  /** 这张卡会让文风变成什么样（详细，给用户看 + 喂给模型） */
  effect: string
  /** 多段原文，帮用户直接感受风格 */
  quotes: string[]
  /** 应用后写入【文笔】画布的完整文案 */
  applyText: string
}

export const STYLE_CARD_GROUPS: StyleCardGroup[] = [
  '中国现当代',
  '中国古典·武侠',
  '日本文学',
  '欧美·现代主义与经典',
  '俄苏·欧洲大陆',
  '法国·拉美·后现代',
  '类型文学',
  '诗歌·戏剧·随笔',
  '网络文学',
  '我的文风卡',
]

/** 自定义卡的分组名（StyleForge 生成的卡都归到这里） */
export const CUSTOM_CARD_GROUP: StyleCardGroup = '我的文风卡'

